import{_ as a}from"./chunks/console-dashboard.BBe1OlBh.js";import{_ as t,o as s,c as o,a3 as n}from"./chunks/framework.DhF4LrUq.js";const b=JSON.parse('{"title":"Read the dashboards","description":"Dashboards and analytics - read the organization dashboard, the tenant dashboard, and the release-health picture they compute.","frontmatter":{"description":"Dashboards and analytics - read the organization dashboard, the tenant dashboard, and the release-health picture they compute."},"headers":[],"relativePath":"how-to/console/analytics-and-dashboards.md","filePath":"how-to/console/analytics-and-dashboards.md"}'),r={name:"how-to/console/analytics-and-dashboards.md"};function i(d,e,h,l,c,p){return s(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="read-the-dashboards" tabindex="-1">Read the dashboards <a class="header-anchor" href="#read-the-dashboards" aria-label="Permalink to &quot;Read the dashboards&quot;">​</a></h1><p>ShipperDog computes two landing views — one for the organization, one per tenant — and both refresh themselves every 30 seconds. Nothing here needs configuring: the dashboards are reads over the same facts every other screen enforces.</p><p><img src="'+a+'" alt="The organization dashboard"></p><p>What the numbers mean — the feedback-to-metric-to-gate loop — is covered in <a href="/shipperdog/snapshot/concepts/feedback-analytics">feedback and analytics</a>.</p><h2 id="the-organization-dashboard" tabindex="-1">The organization dashboard <a class="header-anchor" href="#the-organization-dashboard" aria-label="Permalink to &quot;The organization dashboard&quot;">​</a></h2><p>Open <strong>Dashboard</strong> (the Console&#39;s landing screen). You get:</p><ul><li><strong>Six counts</strong> — Applications, Tenants, Active releases, Pending approvals, Testing, Production.</li><li><strong>Release health per application</strong> — one row per application with its derived health: <code>HEALTHY</code>, <code>TESTING</code>, <code>BLOCKED</code>, or <code>INACTIVE</code>. The derivation is the server&#39;s, not a client&#39;s guess.</li><li><strong>Your pending actions</strong> — the approvals and decisions <em>you</em> personally can act on, filtered to your roles, each row deep-linking to the release screen it acts on and wearing a <strong>Decide</strong> chip when the call is yours.</li></ul><p>The pending-actions list is the working queue: an approval waiting on your signature surfaces here first, one click from the <a href="/shipperdog/snapshot/how-to/console/approvals">approval step</a>.</p><h2 id="the-tenant-dashboard" tabindex="-1">The tenant dashboard <a class="header-anchor" href="#the-tenant-dashboard" aria-label="Permalink to &quot;The tenant dashboard&quot;">​</a></h2><p>Tenants — <strong>Dashboard</strong> on a tenant&#39;s row. The tenant-grain view carries:</p><ul><li>the tenant block&#39;s four counts,</li><li>the in-flight releases targeting this tenant (each deep-linking to its release screen),</li><li>the <strong>downloads trend over the last seven days</strong> — one folded point per day from the tenant&#39;s download series.</li></ul><p>Tenant admins live here; it is their entire Console. See the <a href="/shipperdog/snapshot/roles/tenant-admin">tenant-admin quickstart</a>.</p><h2 id="where-the-deeper-numbers-live" tabindex="-1">Where the deeper numbers live <a class="header-anchor" href="#where-the-deeper-numbers-live" aria-label="Permalink to &quot;Where the deeper numbers live&quot;">​</a></h2><p>The dashboards are rollups; the grain lives on the artifacts they summarize:</p><ul><li>Per-release feedback and its open-critical count: <a href="/shipperdog/snapshot/how-to/console/feedback-triage">triage feedback</a>.</li><li>Per-release gate states and observed values: <a href="/shipperdog/snapshot/how-to/console/quality-gates">quality gates</a>.</li><li>Per-channel distribution standing (TestFlight beta review, Play processing): the release dashboard&#39;s Channel distributions block.</li></ul><div class="tip custom-block"><p class="custom-block-title">Downloads drive gates</p><p>Metric-backed gates (<code>crash-free-threshold</code>, <code>open-critical-bugs</code>) resolve from these same analytics feeds at evaluation time, fail-closed until data lands — a dashboard that shows no downloads yet also means a crash-free gate that cannot pass yet.</p></div><p><strong>Related guides:</strong> <a href="/shipperdog/snapshot/how-to/console/releases">work with releases</a> · <a href="/shipperdog/snapshot/how-to/console/quality-gates">quality gates</a> · <a href="/shipperdog/snapshot/roles/tenant-admin">tenant-admin quickstart</a></p>',17)])])}const f=t(r,[["render",i]]);export{b as __pageData,f as default};
